"""Static assets for the isolated first-party Test Center package."""

TEST_CENTER_INDEX = """<!doctype html>
<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><link rel=\"stylesheet\" href=\"module.css\"></head>
<body><main id=\"root\"></main><script src=\"module.js\"></script></body></html>"""

TEST_CENTER_JS = r"""
const api = '/api/modules/autody-test-center';
const root = document.getElementById('root');
const moduleId = 'autody-test-center';
const warning = '卸载测试中心后，所有测试历史、测试设置和测试目标覆盖将被永久删除。AutoDy 的正常好友、文案、发送记录和浏览器数据不会受到影响。';
const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const card = (title, body, extra = '') => `<section class="card"><div class="card-heading"><h2>${title}</h2>${extra}</div>${body}</section>`;
const rows = (items, empty, render) => items?.length ? `<div class="rows">${items.map(render).join('')}</div>` : `<p class="empty">${empty}</p>`;
async function get(path, fallback) { try { const response = await fetch(api + path); return response.ok ? await response.json() : fallback; } catch { return fallback; } }
async function request(path, method = 'POST', payload = {}) { const response = await fetch(api + path, { method, headers: {'Content-Type':'application/json'}, body: JSON.stringify(payload) }); if (!response.ok) throw new Error(await response.text() || '请求未完成'); return response.json(); }
function resizeHost() { const height = Math.ceil(Math.max(document.documentElement.scrollHeight, document.body.scrollHeight, 760)); window.parent.postMessage({type:'autody-test-center:resize', moduleId, height}, window.location.origin); }
new ResizeObserver(resizeHost).observe(document.documentElement);
function openDialog(id) { document.getElementById(id).hidden = false; resizeHost(); }
function closeDialog(id) { document.getElementById(id).hidden = true; resizeHost(); }
function dialogMarkup() { return `<div class="modal" id="details-dialog" role="dialog" aria-modal="true" aria-labelledby="details-title" hidden><div class="modal-card"><div class="modal-title"><h2 id="details-title">技术详情</h2><button class="icon-button" data-close="details-dialog" aria-label="关闭">×</button></div><pre id="details-content"></pre></div></div><div class="modal" id="diagnostics-dialog" role="dialog" aria-modal="true" aria-labelledby="diagnostics-title" hidden><div class="modal-card"><div class="modal-title"><h2 id="diagnostics-title">运行环境诊断</h2><button class="icon-button" data-close="diagnostics-dialog" aria-label="关闭">×</button></div><p id="diagnostics-content"></p></div></div><div class="modal" id="remove-dialog" role="dialog" aria-modal="true" aria-labelledby="remove-dialog-title" hidden><div class="modal-card"><h2 id="remove-dialog-title">确认移除测试中心</h2><p>${warning}</p><div class="dialog-actions"><button class="secondary" id="remove-cancel">取消</button><button class="danger" id="remove-confirm">移除测试中心</button></div></div></div>`; }
function bindCommon(status) {
  root.querySelectorAll('[data-close]').forEach(button => button.onclick = () => closeDialog(button.dataset.close));
  document.getElementById('show-details').onclick = () => { document.getElementById('details-content').textContent = JSON.stringify(status, null, 2); openDialog('details-dialog'); };
  document.getElementById('show-diagnostics').onclick = () => openDialog('diagnostics-dialog');
  document.getElementById('remove').onclick = () => openDialog('remove-dialog');
  document.getElementById('remove-cancel').onclick = () => closeDialog('remove-dialog');
  document.getElementById('remove-confirm').onclick = async event => { const button = event.currentTarget; button.disabled = true; try { await request('/uninstall'); window.parent.postMessage({type:'autody-test-center:removed', moduleId}, window.location.origin); } catch (error) { button.disabled = false; document.getElementById('module-status').textContent = `移除失败：${error.message}`; } };
}
async function load() {
  const [plan, failed, preflight, diagnostics, history] = await Promise.all([get('/today-plan',{targets:[]}),get('/failed-targets',{items:[]}),get('/preflight/status',{result:null,running:false}),get('/diagnostics',{}),get('/history',{items:[]})]);
  const targets = plan.targets || [];
  const failedRows = rows(failed.items, '今日无异常目标。', item => `<article><strong>${escapeHtml(item.display_name)}</strong><span>${escapeHtml(item.explanation || item.reason_code || '需要关注')}</span><button class="text-button details" data-detail="${escapeHtml(item.target_id)}">查看详情</button></article>`);
  const planRows = rows(targets, '今日没有待发送计划。', item => `<article><strong>${escapeHtml(item.display_name)}</strong><span>${escapeHtml(item.planned_at || '待安排')} · ${escapeHtml(item.status || '待执行')}</span></article>`);
  const historyRows = rows(history.items, '暂无模块测试历史。', item => `<article><strong>${escapeHtml(item.title)}</strong><span>${escapeHtml(item.created_at)}</span></article>`);
  const options = targets.map(item => `<option value="${escapeHtml(item.target_id)}">${escapeHtml(item.display_name)}</option>`).join('');
  root.innerHTML = `<header class="module-header"><div><p class="eyebrow">可选模块 · 只读模式</p><h1>测试中心</h1><p>用于只读预检、任务诊断和安全测试；不会输入、准备或发送任何消息。</p></div><span class="badge">${preflight.running ? '预检运行中' : '模块就绪'}</span></header><div class="summary-grid"><article><span>发送前自检</span><strong>${escapeHtml(preflight.result?.global_status || '尚未运行')}</strong></article><article><span>异常目标</span><strong>${failed.items?.length || 0}</strong></article><article><span>今日计划</span><strong>${targets.length}</strong></article></div>${card('发送前自检', `<p class="muted">${preflight.running ? `正在执行：${preflight.progress?.completed_targets || 0}/${preflight.progress?.total_targets || 0}` : '只检查登录、目标、会话、编辑器和发送控件可用性。'}</p><div class="actions"><button id="run-all">开始完整预检</button><label class="select-label">单个目标<select id="one-target"><option value="">请选择</option>${options}</select></label><button class="secondary" id="run-one">开始单目标预检</button><button class="secondary" id="cancel">取消预检</button></div><p class="status-line" id="module-status" aria-live="polite"></p>`) }<div class="two-column">${card('今日异常目标', failedRows)}${card('今日发送计划', planRows)}</div>${card('单目标高级设置', `<p class="muted">选择目标后可保存模块专属的测试覆盖；它们不会写入正常目标记录。</p><div class="actions"><select id="settings-target"><option value="">请选择目标</option>${options}</select><button class="secondary" id="save-settings">保存模块测试覆盖</button><button class="secondary" id="reset-settings">重置模块测试覆盖</button></div>`)}${card('运行环境', `<p>${escapeHtml(diagnostics.environment || '本机环境已加载；测试中心仅执行只读检查。')}</p><div class="actions"><button class="secondary" id="show-diagnostics">打开环境诊断</button><button class="text-button" id="show-details">展开技术详情</button></div>`)}${card('安全测试工具', `<p class="muted">夹具和受控故障仅写入模块数据目录，绝不调用真实发送。</p><div class="actions"><button class="secondary" id="fixture">生成安全夹具数据</button><button class="secondary" id="simulate">启动受控失败模拟</button></div>`)}${card('测试历史与进度', historyRows)}${card('模块管理', `<p>测试中心是可选模块。移除后不会影响 AutoDy 的正常好友、文案、定时任务、浏览器资料和发送记录。</p><div class="actions"><button class="secondary danger-outline" id="remove">移除测试中心</button></div>`) }${dialogMarkup()}`;
  const statusLine = document.getElementById('module-status');
  const run = async ids => { try { await request('/preflight/run', 'POST', {target_ids: ids}); statusLine.textContent = '已开始只读预检；不会发送消息。'; await load(); } catch (error) { statusLine.textContent = `预检未完成：${error.message}`; } };
  document.getElementById('run-all').onclick = () => run(null);
  document.getElementById('run-one').onclick = () => { const value = document.getElementById('one-target').value; if (!value) { statusLine.textContent = '请先选择一个目标。'; return; } run([value]); };
  document.getElementById('cancel').onclick = async () => { await request('/preflight/cancel'); statusLine.textContent = '已请求取消只读预检。'; };
  const save = async reset => { const id = document.getElementById('settings-target').value; if (!id) { statusLine.textContent = '请先选择一个目标。'; return; } try { await request(`/targets/${encodeURIComponent(id)}/settings`, 'PUT', {reset_overrides: reset}); statusLine.textContent = reset ? '模块测试覆盖已重置。' : '模块测试覆盖已保存。'; } catch (error) { statusLine.textContent = `保存失败：${error.message}`; } };
  document.getElementById('save-settings').onclick = () => save(false);
  document.getElementById('reset-settings').onclick = () => save(true);
  document.getElementById('fixture').onclick = async () => { await request('/fixtures'); statusLine.textContent = '已生成安全夹具数据。'; await load(); };
  document.getElementById('simulate').onclick = async () => { await request('/simulate-failure'); statusLine.textContent = '已记录受控失败模拟。'; await load(); };
  root.querySelectorAll('.details').forEach(button => button.onclick = () => { document.getElementById('details-content').textContent = `目标 ID：${button.dataset.detail}\n只读诊断：不会输入、准备或发送消息。`; openDialog('details-dialog'); });
  bindCommon(diagnostics);
  resizeHost();
}
load();
"""

TEST_CENTER_CSS = r"""
*{box-sizing:border-box}html,body{margin:0;min-width:320px;background:#f6f8fc;color:#15243b;font:14px/1.55 "Segoe UI","Microsoft YaHei",sans-serif}#root{padding:24px}.module-header{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;margin-bottom:20px}.eyebrow{margin:0 0 6px;color:#77869a;font-size:12px}.module-header h1{margin:0;color:#0b1830;font-size:27px;letter-spacing:-.04em}.module-header p:not(.eyebrow){margin:6px 0 0;color:#738097}.badge{padding:5px 10px;border-radius:99px;color:#1769e8;background:#eaf3ff;font-size:12px;font-weight:700;white-space:nowrap}.summary-grid,.two-column{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.summary-grid article,.card{border:1px solid #dfe7f0;border-radius:12px;background:#fff;box-shadow:0 7px 18px rgba(27,54,88,.05)}.summary-grid article{padding:16px}.summary-grid span{display:block;color:#7d899b;font-size:12px}.summary-grid strong{display:block;margin-top:5px;color:#1b3150;font-size:20px}.card{margin-top:16px;padding:18px}.card-heading{display:flex;justify-content:space-between;gap:12px}.card h2{margin:0;font-size:16px}.muted,.empty,.status-line{color:#718096}.actions{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-top:13px}button,select{min-height:38px;border-radius:8px;font:inherit}button{border:1px solid #1769e8;padding:0 13px;color:#fff;background:#1769e8;cursor:pointer;font-weight:650}button:hover{filter:brightness(.96)}button:focus-visible,select:focus-visible{outline:2px solid #72a8ff;outline-offset:2px}.secondary{border-color:#d3ddea;color:#2c405d;background:#fff}.danger-outline{border-color:#e7bbc0;color:#a53845;background:#fff}.select-label{display:flex;align-items:center;gap:7px;color:#5f6f85}select{border:1px solid #ccd7e5;padding:0 9px;color:#243550;background:#fff}.two-column{grid-template-columns:repeat(2,minmax(0,1fr));align-items:start}.rows article{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:3px 10px;padding:11px 0;border-top:1px solid #edf1f6}.rows article:first-child{border-top:0}.rows strong{min-width:0}.rows span{grid-column:1;color:#728095;font-size:12px}.text-button{min-height:auto;border:0;padding:0;color:#1769e8;background:transparent;font-size:12px}.modal[hidden]{display:none}.modal{position:fixed;z-index:10;inset:0;display:grid;place-items:center;padding:24px;background:rgba(13,29,50,.52)}.modal-card{width:min(620px,100%);max-height:calc(100vh - 48px);overflow:auto;border-radius:12px;padding:22px;background:#fff;box-shadow:0 18px 50px rgba(6,22,43,.3)}.modal-card h2{margin:0 0 12px}.modal-card pre{overflow:auto;padding:12px;border-radius:8px;background:#f3f6fa;font:12px/1.5 Consolas,monospace;white-space:pre-wrap}.modal-title{display:flex;justify-content:space-between;align-items:center}.icon-button{min-height:32px;width:32px;border:0;padding:0;color:#52657e;background:#eef3f8;font-size:20px}.dialog-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:20px}.danger{border-color:#b83e4d;color:#fff;background:#b83e4d}@media(max-width:720px){#root{padding:16px}.module-header{flex-direction:column;gap:10px}.summary-grid,.two-column{grid-template-columns:1fr}.actions,.select-label{align-items:stretch;flex-direction:column}.actions button,.actions select{width:100%}}
"""
